#include <iostream>
#include <vector>
using namespace std;

int lowerBound(const vector<int>& a, int target) {
    int left = 0, right = (int)a.size() - 1, answer = (int)a.size();
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] >= target) {
            answer = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return answer;
}

int main() {
    vector<int> a = {1, 3, 5, 7, 9};
    cout << lowerBound(a, 7) << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool check(long long mid, const vector<int>& a, long long k) {
    // Ví dụ: có thể biến mảng thành median >= mid bằng tối đa k phép +1.
    long long need = 0;
    int n = (int)a.size();
    for (int i = n / 2; i < n; ++i) {
        if (a[i] < mid) need += mid - a[i];
        if (need > k) return false;
    }
    return need <= k;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    sort(a.begin(), a.end());

    long long left = a[n / 2], right = a[n / 2] + k, answer = left;
    while (left <= right) {
        long long mid = left + (right - left) / 2;
        if (check(mid, a, k)) {
            answer = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    cout << answer << '\n';
    return 0;
}
